package com.sakalti.modifier;
import net.minecraft.world.effect.*; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.level.Level; import net.minecraft.world.item.ItemStack; import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.context.ToolAttackContext; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class AuroVisionModifier extends Modifier { @Override public int afterEntityHit(IToolStackView tool,int level,ToolAttackContext ctx,float damage){LivingEntity a=ctx.getAttacker();if(a!=null&&!a.level().isClientSide){a.addEffect(new MobEffectInstance(MobEffects.GLOWING,20,4));a.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE,20,4));}return 0;} @Override public void onInventoryTick(IToolStackView tool,int level,Level world,LivingEntity e,int slot,boolean selected,boolean correct,ItemStack stack){if(!world.isClientSide&&!tool.isBroken()&&correct)e.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION,220,0,false,true));}}
